/// Synthetic WASM fixtures for the engine host tests (batch 02).
///
/// The architecture guard (`test/architecture_guard_test.dart`) allows exactly
/// one `.wasm` blob in the app tree (`assets/engine/moonviz.wasm`), so the
/// fixtures are **generated byte-for-byte** here instead of being checked in
/// as binaries. The encoding is hand-written WASM MVP: tiny, deterministic,
/// and reviewable (every opcode below is a spec literal).
///
/// One module exports everything the tests need:
///
/// * `memory` — 1 page minimum, 8 maximum;
/// * `spin()` — `loop { br 0 }`: never returns; only fuel or a killed isolate
///   can stop it;
/// * `busy(i32) -> i32` — countdown loop: a bounded call used to hold the
///   worker busy while the test watches the UI isolate event loop;
/// * `boom()` — `unreachable`: a deterministic trap;
/// * `make_string() -> i32` — grows memory by two pages, then writes
///   `[len=5][UTF-16LE "hello"]` at address 131072 (beyond the pre-grow
///   65536-byte view) and returns the string pointer. Reading it through a
///   stale [WasmMemory.view] is the documented use-after-grow hazard.
library;

import 'dart:convert';
import 'dart:typed_data';

/// Address of the UTF-16 string written by `make_string` (in the grown pages).
const int kFixtureStringPtr = 131072;

/// The UTF-16 string `make_string` writes.
const String kFixtureString = 'hello';

/// Builds the combined fixture module described in the library docs.
Uint8List buildFixtureModule() {
  // Types: t0 = () -> (), t1 = (i32) -> (i32), t2 = () -> (i32).
  final types = _section(1, _vec(<List<int>>[
    <int>[0x60, ..._uleb(0), ..._uleb(0)],
    <int>[0x60, ..._uleb(1), 0x7f, ..._uleb(1), 0x7f],
    <int>[0x60, ..._uleb(0), ..._uleb(1), 0x7f],
  ]));

  // Function indices: 0 spin:t0, 1 busy:t1, 2 boom:t0, 3 make_string:t2.
  final functions = _section(3, _vec(<List<int>>[
    _uleb(0),
    _uleb(1),
    _uleb(0),
    _uleb(2),
  ]));

  // Memory: min 1 page, max 8 pages (512 KiB max — still tiny).
  final memory = _section(5, _vec(<List<int>>[
    <int>[0x01, ..._uleb(1), ..._uleb(8)],
  ]));

  final exports = _section(7, _vec(<List<int>>[
    <int>[..._name('memory'), 0x02, ..._uleb(0)],
    <int>[..._name('spin'), 0x00, ..._uleb(0)],
    <int>[..._name('busy'), 0x00, ..._uleb(1)],
    <int>[..._name('boom'), 0x00, ..._uleb(2)],
    <int>[..._name('make_string'), 0x00, ..._uleb(3)],
  ]));

  final code = _section(10, _vec(<List<int>>[
    _body(<int>[0x00, 0x03, 0x40, 0x0c, 0x00, 0x0b, 0x0b]), // spin
    _body(<int>[
      0x01, 0x01, 0x7f, // one i32 local
      0x20, 0x00, // local.get 0
      0x21, 0x01, // local.set 1
      0x02, 0x40, // block
      0x03, 0x40, // loop
      0x20, 0x01, //   local.get 1
      0x45, //         i32.eqz
      0x0d, 0x01, //   br_if 1
      0x20, 0x01, //   local.get 1
      0x41, 0x01, //   i32.const 1
      0x6b, //         i32.sub
      0x21, 0x01, //   local.set 1
      0x0c, 0x00, //   br 0
      0x0b, //       end loop
      0x0b, //       end block
      0x20, 0x01, // local.get 1
      0x0b, //       end func
    ]),
    _body(<int>[0x00, 0x00, 0x0b]), // boom: unreachable
    _body(<int>[
      0x00, // no locals
      ..._i32(2), 0x40, 0x00, 0x1a, // memory.grow 2; drop
      // header u32 5 at ptr-4
      ..._i32(kFixtureStringPtr - 4), ..._i32(5), 0x36, 0x02, 0x00,
      // UTF-16LE code units at ptr
      for (var i = 0; i < kFixtureString.length; i++) ...<int>[
        ..._i32(kFixtureStringPtr + i * 2),
        ..._i32(kFixtureString.codeUnitAt(i)),
        0x3b, 0x01, 0x00, // i32.store16 align=1 offset=0
      ],
      ..._i32(kFixtureStringPtr),
      0x0b,
    ]),
  ]));

  final out = BytesBuilder()
    ..add(<int>[0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00])
    ..add(types)
    ..add(functions)
    ..add(memory)
    ..add(exports)
    ..add(code);
  return out.takeBytes();
}

/// Unsigned LEB128.
List<int> _uleb(int value) {
  final out = <int>[];
  var n = value;
  while (true) {
    final byte = n & 0x7f;
    n >>= 7;
    if (n != 0) {
      out.add(byte | 0x80);
    } else {
      out.add(byte);
      return out;
    }
  }
}

/// Signed LEB128 (needed for `i32.const`; +64 encodes as `c0 00`).
List<int> _sleb(int value) {
  final out = <int>[];
  var n = value;
  while (true) {
    final byte = n & 0x7f;
    n >>= 7; // Dart's >> keeps the sign for negative ints
    final done = (n == 0 && (byte & 0x40) == 0) || (n == -1 && (byte & 0x40) != 0);
    if (done) {
      out.add(byte);
      return out;
    }
    out.add(byte | 0x80);
  }
}

List<int> _i32(int value) => <int>[0x41, ..._sleb(value)];

List<int> _name(String value) {
  final bytes = utf8.encode(value);
  return <int>[..._uleb(bytes.length), ...bytes];
}

List<int> _vec(List<List<int>> items) => <int>[
      ..._uleb(items.length),
      for (final item in items) ...item,
    ];

List<int> _section(int id, List<int> payload) => <int>[
      id,
      ..._uleb(payload.length),
      ...payload,
    ];

List<int> _body(List<int> instructions) => <int>[
      ..._uleb(instructions.length),
      ...instructions,
    ];
